/* From Uiverse.io by njesenberger - Tags: switch, squishy, toggle, liquid, toggle switch, on off toggle switch */
.__UIV_SCOPE__ .toggle-container {
  --active-color: #1868e3;
  --inactive-color: #d3d3d6;
  position: relative;
  aspect-ratio: 292 / 142;
  height: 1.875em;
}

.__UIV_SCOPE__ .toggle-input {
  appearance: none;
  margin: 0;
  position: absolute;
  z-index: 1;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
}

.__UIV_SCOPE__ .toggle {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.__UIV_SCOPE__ .toggle-background {
  fill: var(--inactive-color);
  transition: fill .4s;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle .toggle-background {
  fill: var(--active-color);
}

.__UIV_SCOPE__ .toggle-circle-center {
  transform-origin: center;
  transition: transform .6s;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle .toggle-circle-center {
  transform: translateX(150px);
}

.__UIV_SCOPE__ .toggle-circle {
  transform-origin: center;
  transition: transform .45s;
  backface-visibility: hidden;
}

.__UIV_SCOPE__ .toggle-circle.left {
  transform: scale(1);
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle .toggle-circle.left {
  transform: scale(0);
}

.__UIV_SCOPE__ .toggle-circle.right {
  transform: scale(0);
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle .toggle-circle.right {
  transform: scale(1);
}

.__UIV_SCOPE__ .toggle-icon {
  transition: fill .4s;
}

.__UIV_SCOPE__ .toggle-icon.on {
  fill: var(--inactive-color);
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle .toggle-icon.on {
  fill: #fff;
}

.__UIV_SCOPE__ .toggle-icon.off {
  fill: #eaeaec;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle .toggle-icon.off {
  fill: var(--active-color);
}
